insert into hygieia.exercises (id, slug, name_el, name_en, cue_el, cue_en, workout_type, level, muscle_groups, equipment_el, equipment_en) values
  ('83dae314-a2d3-33fa-3301-414dd48880d9'::uuid, 'assisted-pull-up', 'Υποβοηθούμενες έλξεις στο μηχάνημα', 'Assisted pull-up (machine)', 'Γονατίστε στο μαξιλάρι και πιάστε τη μπάρα με πρηνή λαβή λίγο πιο ανοιχτά από τους ώμους. Τραβήξτε πρώτα τις ωμοπλάτες κάτω, μετά τραβηχτείτε μέχρι το πηγούνι να περάσει τη μπάρα και κατεβείτε ως κάτω ελεγχόμενα. Μειώνετε τη βοήθεια με τις εβδομάδες, όσο δυναμώνετε.', 'Kneel on the pad with an overhand grip a little wider than the shoulders. Pull the shoulder blades down first, then pull until the chin clears the bar, and lower all the way under control. Use less assistance over the weeks as you get stronger.', 'gym', 'intermediate', array['back','biceps','core']::text[], 'Μηχάνημα', 'Machine'),
  ('c4022b49-21c5-e07c-72db-6301363d167e'::uuid, 'band-lateral-walk', 'Πλάγια βήματα με λάστιχο', 'Banded lateral walk', 'Περάστε ένα λάστιχο λίγο πάνω από τα γόνατα, καθίστε σε ελαφρύ κάθισμα και κάντε αργά πλάγια βήματα, κρατώντας το λάστιχο τεντωμένο και τα γόνατα προς τα έξω, πάνω από τα δάχτυλα. Μετρήστε κάθε βήμα και επαναλάβετε προς την άλλη πλευρά.', 'Loop a band just above the knees, sit into a quarter squat and take slow side steps, keeping tension on the band and the knees pushed out over the toes. Count each step and repeat in the other direction.', 'home', 'beginner', array['glutes','adductors']::text[], 'Λάστιχο αντίστασης', 'Resistance band'),
  ('a2fcfeda-4b64-9d85-4758-9f87f96f19f3'::uuid, 'bodyweight-good-morning', 'Good morning με το βάρος του σώματος', 'Bodyweight good morning', 'Χέρια ελαφρά πίσω από το κεφάλι, γόνατα χαλαρά. Σπρώξτε τους γοφούς πίσω και γείρετε το στήθος μπροστά με ίσια πλάτη μέχρι να νιώσετε τους οπίσθιους μηριαίους, και σφίξτε τους γλουτούς για να σηκωθείτε. Πρόβα της κάμψης από τους γοφούς πριν μπει βάρος.', 'Hands lightly behind the head, knees soft. Push the hips back and tip the chest forward with a flat back until you feel the hamstrings, then squeeze the glutes to stand. A rehearsal of the hip hinge before loading it.', 'home', 'beginner', array['hamstrings','glutes','back']::text[], null, null),
  ('6d1ae27e-0477-425b-84f5-259a2223a82b'::uuid, 'dead-bug', 'Dead bug (αντίθετα χέρι-πόδι ανάσκελα)', 'Dead bug', 'Ξαπλώστε ανάσκελα, χέρια ψηλά, γοφοί και γόνατα στις 90 μοίρες, η μέση ελαφρά πιεσμένη στο πάτωμα. Απλώστε αργά το ένα χέρι και το αντίθετο πόδι, εκπνεύστε πλήρως και επιστρέψτε. Εναλλάξτε πλευρές χωρίς να καμπουριάζει η μέση προς τα πάνω.', 'Lie on your back, arms up, hips and knees at 90 degrees, lower back gently pressed into the floor. Reach one arm and the opposite leg away slowly, exhale fully, and return. Alternate sides without letting the back arch.', 'home', 'beginner', array['core','hip-flexors']::text[], 'Στρώμα', 'Mat'),
  ('80ca4c3d-7346-a411-6208-00adacb3ae89'::uuid, 'dumbbell-floor-press', 'Πιέσεις στήθους με αλτήρες στο πάτωμα', 'Dumbbell floor press', 'Ξαπλώστε ανάσκελα με λυγισμένα γόνατα και έναν αλτήρα σε κάθε χέρι πάνω από το στήθος. Κατεβάστε μέχρι οι βραχίονες να ακουμπήσουν το πάτωμα σε γωνία περίπου 45 μοιρών από το σώμα, κρατήστε στιγμιαία και πιέστε ξανά πάνω. Εκπνεύστε στην πίεση.', 'Lie on your back, knees bent, a dumbbell in each hand above the chest. Lower until the upper arms touch the floor at about 45 degrees from the body, pause, and press back up. Exhale as you press.', 'home', 'beginner', array['chest','triceps','shoulders']::text[], 'Αλτήρες', 'Dumbbells'),
  ('b13f262b-9923-85cf-b6e4-53473898a006'::uuid, 'dumbbell-hip-thrust', 'Hip thrust με αλτήρα', 'Dumbbell hip thrust', 'Πάνω μέρος της πλάτης στην άκρη καναπέ ή σταθερού πάγκου, ένας αλτήρας πάνω στους γοφούς, πέλματα στο πάτωμα. Σπρώξτε με τις φτέρνες μέχρι το σώμα να είναι ευθεία από ώμους ως γόνατα, σφίξτε τους γλουτούς για ένα δευτερόλεπτο και κατεβείτε αργά. Εκπνεύστε στην άνοδο.', 'Upper back against the edge of a sofa or sturdy bench, a dumbbell held on the hips, feet flat. Drive through the heels until the body is level from shoulders to knees, squeeze the glutes for a second, and lower slowly. Exhale as you lift.', 'home', 'intermediate', array['glutes','hamstrings','core']::text[], 'Αλτήρας και καναπές ή σταθερός πάγκος', 'Dumbbell and sofa or sturdy bench'),
  ('e0db3a63-604b-f7aa-389d-0f95b98216b4'::uuid, 'dumbbell-romanian-deadlift', 'Ρουμανικές άρσεις θανάτου με αλτήρες', 'Dumbbell Romanian deadlift', 'Αλτήρες μπροστά από τους μηρούς, γόνατα ελαφρά λυγισμένα. Σπρώξτε τους γοφούς πίσω και κατεβάστε τα βάρη κατά μήκος των ποδιών με ίσια πλάτη μέχρι να νιώσετε τους οπίσθιους μηριαίους να τεντώνουν, και σπρώξτε τους γοφούς μπροστά για να σταθείτε όρθιοι. Εκπνεύστε στην άνοδο.', 'Dumbbells in front of the thighs, knees softly bent. Push the hips back and slide the weights down the legs with a flat back until you feel the hamstrings stretch, then drive the hips forward to stand tall. Exhale on the way up.', 'home', 'beginner', array['hamstrings','glutes','back']::text[], 'Αλτήρες', 'Dumbbells'),
  ('c65f4dd0-67a2-f5d8-d314-44dfa0019d98'::uuid, 'farmer-carry', 'Μεταφορά αγρότη (farmer carry)', 'Farmer carry', 'Σηκώστε έναν βαρύ αλτήρα σε κάθε χέρι με ίσια πλάτη, σταθείτε όρθιοι με τους ώμους χαμηλά και μακριά από τα αυτιά και περπατήστε με μικρά, σταθερά βήματα. Αναπνέετε κανονικά και αφήστε τα βάρη κάτω με την ίδια κάμψη από τους γοφούς.', 'Pick up a heavy dumbbell in each hand with a flat back, stand tall with the shoulders down and away from the ears, and walk with short, steady steps. Breathe normally and set the weights down with the same flat-back hinge.', 'gym', 'beginner', array['forearms','core','shoulders']::text[], 'Αλτήρες', 'Dumbbells'),
  ('63843fe8-9a08-f199-18aa-22e1252da523'::uuid, 'goblet-squat-home', 'Goblet squat με αλτήρα', 'Goblet squat with a dumbbell', 'Κρατήστε έναν αλτήρα όρθιο κολλητά στο στήθος, πέλματα λίγο πιο ανοιχτά από τη λεκάνη. Καθίστε ανάμεσα στα γόνατα με το στήθος ψηλά και τις φτέρνες κάτω και σηκωθείτε σπρώχνοντας το πάτωμα. Εισπνοή στην κάθοδο, εκπνοή στην άνοδο.', 'Hold one dumbbell upright against the chest, feet a little wider than the hips. Sit down between the knees with the chest tall and the heels down, then stand by pushing the floor away. Inhale down, exhale up.', 'home', 'beginner', array['quads','glutes','core']::text[], 'Αλτήρας', 'Dumbbell'),
  ('3c039eec-78f9-b9ff-efeb-89e2f1d3182d'::uuid, 'hip-thrust', 'Hip thrust με μπάρα', 'Barbell hip thrust', 'Πάνω μέρος της πλάτης στην άκρη του πάγκου, μπάρα με προστατευτικό πάνω στους γοφούς, πέλματα στο πάτωμα στο άνοιγμα της λεκάνης. Σπρώξτε με τις φτέρνες μέχρι οι γοφοί να έρθουν στην ευθεία γονάτων και ώμων, κρατήστε στιγμιαία σφίγγοντας τους γλουτούς και κατεβείτε ελεγχόμενα. Εκπνεύστε στην άνοδο.', 'Upper back on the bench edge, padded bar across the hips, feet flat about hip-width apart. Drive through the heels until the hips are level with the knees and shoulders, pause and squeeze the glutes, then lower under control. Exhale as you lift.', 'gym', 'beginner', array['glutes','hamstrings','core']::text[], 'Μπάρα και πάγκος', 'Barbell and bench'),
  ('fc5da09b-d516-957b-5f84-b654940fe2ec'::uuid, 'seated-leg-curl', 'Καθιστές κάμψεις γονάτων στο μηχάνημα', 'Seated leg curl', 'Ρυθμίστε το μαξιλαράκι λίγο πάνω από τις φτέρνες και το γόνατο στην ευθεία του άξονα του μηχανήματος. Λυγίστε τα γόνατα φέρνοντας τις φτέρνες κάτω και πίσω σε ομαλό τόξο, κρατήστε στιγμιαία και επιστρέψτε αργά χωρίς να χτυπήσουν τα βάρη. Εκπνεύστε στην κάμψη.', 'Set the pad just above the heels and the knee joint in line with the machine pivot. Curl the heels down and back in a smooth arc, pause, and return slowly without letting the stack slam. Exhale as you curl.', 'gym', 'beginner', array['hamstrings']::text[], 'Μηχάνημα', 'Machine'),
  ('1a9b83b8-711f-d32d-f6f2-8b0d4d3ec16c'::uuid, 'side-plank', 'Πλάγια σανίδα', 'Side plank', 'Αγκώνας κάτω από τον ώμο, πέλματα το ένα πάνω στο άλλο ή το ένα μπροστά, σώμα σε μία ευθεία από το κεφάλι ως τις φτέρνες. Σηκώστε τους γοφούς και κρατήστε αναπνέοντας σταθερά· στηριχτείτε στο κάτω γόνατο αν πέφτουν οι γοφοί. Κρατήστε και από τις δύο πλευρές.', 'Elbow under the shoulder, feet stacked or staggered, body in one straight line from head to heels. Lift the hips and hold while breathing steadily; drop to the bottom knee if the hips sag. Hold both sides.', 'home', 'intermediate', array['core','shoulders','glutes']::text[], 'Στρώμα', 'Mat'),
  ('7bba752e-a241-8ce7-2ef9-f0c6418a0191'::uuid, 'step-up', 'Ανεβάσματα σε σκαλί', 'Step-up', 'Βάλτε όλο το πέλμα σε σταθερό σκαλί, γείρετε ελαφρά μπροστά και σπρώξτε με αυτή τη φτέρνα για να ανεβείτε όρθιοι, μετά κατεβείτε αργά με το ίδιο πόδι πρώτο. Ολοκληρώστε τις επαναλήψεις στη μία πλευρά πριν αλλάξετε· κρατήστε αλτήρες μόνο όταν νιώθετε σταθεροί.', 'Place the whole foot on a sturdy step, lean slightly forward and drive through that heel to stand up on it, then step down slowly with the same leg leading. Finish all reps on one side before switching; hold dumbbells only once it feels steady.', 'home', 'beginner', array['quads','glutes']::text[], 'Σταθερό σκαλοπάτι ή το πρώτο σκαλί', 'Sturdy step or bottom stair'),
  ('6ac7294b-c85f-642e-6131-86617e308369'::uuid, 'suitcase-carry', 'Μεταφορά βάρους με το ένα χέρι (suitcase carry)', 'Suitcase carry', 'Κρατήστε έναν βαρύ αλτήρα στο πλάι σαν βαλίτσα και περπατήστε όρθιοι χωρίς να γέρνετε προς το βάρος ή μακριά του. Κρατήστε τα πλευρά κάτω και τους ώμους στο ίδιο ύψος, και αλλάξτε χέρι στον επόμενο γύρο.', 'Hold one heavy dumbbell at your side like a suitcase and walk tall without leaning towards or away from it. Keep the ribs down and the shoulders level, then switch hands for the next round.', 'home', 'intermediate', array['core','forearms','shoulders']::text[], 'Αλτήρας', 'Dumbbell')
insert into hygieia.workout_templates (id, slug, track, workout_type, level, intensity, title_el, title_en, duration_min, notes_el, notes_en) values
  ('09ed4a1b-f02a-0aa8-8aae-f59fadb33a44'::uuid, 'women-strength-gym-beginner-full-body-a', 'women-strength', 'gym', 'beginner', 'moderate', 'Δύναμη για γυναίκες · Γυμναστήριο, όλο το σώμα A', 'Strength for women · Gym full body A', 45, 'Η μέρα A ενός προγράμματος δύο ημερών για όλο το σώμα: εναλλάσσεται με τη μέρα B δύο ή τρεις φορές την εβδομάδα, με μία μέρα ξεκούρασης ανάμεσα. Διάλεξε βάρη που σου αφήνουν περίπου δύο καλές επαναλήψεις ακόμη, και όταν όλα τα σετ μιας άσκησης σού φαίνονται εύκολα, βάλε λίγο περισσότερο βάρος την επόμενη φορά. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Day A of a two-day full-body plan: alternate it with day B two or three times a week, with a rest day in between. Pick weights that leave about two good reps in reserve, and when every set of an exercise feels easy, add a little weight next time. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('723c5410-4397-7538-4f91-29b9a9e43e75'::uuid, 'women-strength-gym-beginner-full-body-b', 'women-strength', 'gym', 'beginner', 'low', 'Δύναμη για γυναίκες · Γυμναστήριο, όλο το σώμα B', 'Strength for women · Gym full body B', 45, 'Η μέρα B του προγράμματος δύο ημερών, λίγο πιο ελαφριά, με μηχανήματα και μία άσκηση στο ένα πόδι. Μάθε κάθε κίνηση με βάρος που ελέγχεις σε κάθε επανάληψη· η τακτική προπόνηση με βάρη χτίζει δύναμη και στηρίζει την υγεία των οστών. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Day B of the two-day full-body plan, a slightly lighter session with machines and a single-leg movement. Learn each movement with a weight you control on every rep; regular lifting like this builds strength and supports bone health. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('bb291052-319f-297f-25f4-7380c8f37655'::uuid, 'women-strength-gym-intermediate-lower', 'women-strength', 'gym', 'intermediate', 'high', 'Δύναμη για γυναίκες · Γυμναστήριο, κάτω μέρος σώματος', 'Strength for women · Gym lower body', 65, 'Η βαριά μέρα για το κάτω μέρος σε πρόγραμμα πάνω/κάτω: κάθισμα, κάμψη ισχίου και hip thrust με λιγότερες επαναλήψεις και πλήρη ξεκούραση. Πρόσθεσε βάρος σε μικρά βήματα όταν ολοκληρώνεις όλα τα σετ με δύο επαναλήψεις περιθώριο, και κράτα μια πιο ελαφριά εβδομάδα περίπου κάθε μήνα. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'The heavy lower-body day of an upper/lower split: squat, hinge and hip thrust in lower rep ranges with full rest. Add weight in small steps when you complete every set with two reps to spare, and keep one easier week every month or so. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('30004ead-b201-f185-f667-a79bac19428c'::uuid, 'women-strength-gym-intermediate-upper', 'women-strength', 'gym', 'intermediate', 'moderate', 'Δύναμη για γυναίκες · Γυμναστήριο, πάνω μέρος σώματος', 'Strength for women · Gym upper body', 50, 'Η μέρα για το πάνω μέρος του προγράμματος: έλξεις, πιέσεις και κωπηλατικές για δυνατή πλάτη και ώμους. Σημείωνε τη βοήθεια στο μηχάνημα έλξεων και μείωνέ τη λίγο κάθε λίγες εβδομάδες — η πρώτη σου έλξη χωρίς βοήθεια είναι ρεαλιστικός στόχος. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'The upper-body day of the split: pull-ups, pressing and rowing for a strong back and shoulders. Track the assistance on the pull-up machine and use a little less every few weeks — your first unassisted pull-up is a realistic goal. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('e4fa8035-46c0-7d87-ce09-24db032c4c31'::uuid, 'women-strength-home-beginner-dumbbell', 'women-strength', 'home', 'beginner', 'moderate', 'Δύναμη για γυναίκες · Στο σπίτι με αλτήρες', 'Strength for women · Home dumbbell session', 40, 'Μια προπόνηση δύναμης για όλο το σώμα με ένα ή δύο ζευγάρια αλτήρες και ένα σταθερό σκαλί — δύο ή τρεις φορές την εβδομάδα. Όταν κάνεις όλα τα σετ με καθαρή τεχνική, πρόσθεσε δύο επαναλήψεις· όταν γίνει κι αυτό εύκολο, πήγαινε σε βαρύτερους αλτήρες. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A full-body strength session with one or two pairs of dumbbells and a sturdy step — two or three times a week. When you can do every set with clean form, add two reps; when that is easy too, move to heavier dumbbells. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('4f3dcd55-c056-004c-3a39-857a9a6dc874'::uuid, 'women-strength-home-intermediate-glutes-core', 'women-strength', 'home', 'intermediate', 'moderate', 'Δύναμη για γυναίκες · Στο σπίτι, γλουτοί και κορμός', 'Strength for women · Home glutes and core', 50, 'Μια προπόνηση στο σπίτι για δυνατούς γοφούς, πόδια και κορμό, με αλτήρες, λάστιχο και καναπέ ή σταθερό πάγκο. Κάνε την κάθοδο πιο αργή, περίπου τρία δευτερόλεπτα, πριν πας σε βαρύτερους αλτήρες· δυνατοί γλουτοί και κορμός κάνουν πιο εύκολο το σήκωμα και το ανέβασμα στην καθημερινότητα. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A home session for strong hips, legs and trunk with dumbbells, a band and a sofa or sturdy bench. Slow the lowering phase to about three seconds before you reach for heavier weights; strong glutes and core make everyday lifting and climbing easier. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.')
